    """
    Solve the game theory problem.
    Parse n, k and pile sizes, compute XOR of Grundy values.
    Kevin wins if XOR != 0, otherwise Nicky wins.
    """
    # Helper to compute Grundy numbers
    memo = {}

    def compute_g(n, k, memo, limit=1000000):
        if n in memo:
            return memo[n]

        if n == 0:
            result = 0
        elif n % 2 == 1:
            # Odd n: can only go to n-1
            result = 0  # Based on pattern analysis
        else:
            # Even n = 2x: can go to n-1 or k piles of size x
            g_n_minus_1 = compute_g(n - 1, k, memo)
            if k % 2 == 0:
                # k even: k piles of size x have XOR value 0
                option2 = 0
            else:
                # k odd: k piles of size x have XOR value g(x)
                option2 = compute_g(n // 2, k, memo)

            # mex of {option1, option2}
            s = {g_n_minus_1, option2}
            val = 0
            while val in s:
                val += 1
            result = val

        memo[n] = result
        return result

    lines = input_data.strip().split('\n')
