            if u in memo:
                return memo[u]

            node = nodes[u]

            if node['is_leaf']:
                result = (node['value'], 0)
            else:
                l, r = node['left'], node['right']

                v_left, ops_left = solve(l)
                v_right, ops_right = solve(r)

                total_ops = ops_left + ops_right
                # Pieguy (maximizer) goes on even operation counts, Piegirl (minimizer) on odd
                maximizing = (total_ops % 2 == 0)

                if maximizing:
                    chosen_value = max(v_left, v_right)
                else:
                    chosen_value = min(v_left, v_right)

