         [0, 1, 0]]

    Mn = mat_pow(M, n - 3)

    e1 = Mn[0][0] * 0 + Mn[0][1] * 0 + Mn[0][2] * 1
    e2 = Mn[0][0] * 1 + Mn[0][1] * 0 + Mn[0][2] * 0
    e3 = Mn[0][0] * 0 + Mn[0][1] * 1 + Mn[0][2] * 0

