def cross_product(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull_monotone_chain(points):
    points = sorted(set(points))
    if len(points) <= 2:
        return points

    lower = []
    for p in points:
        while len(lower) > 1 and cross_product(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) > 1 and cross_product(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

def check_origin_in_hull(hull):
    n = len(hull)
    if n < 3:
        return False
    for i in range(n - 1):
        j = (i + 1) % n
        if cross_product(hull[0], hull[i], hull[j]) > 0:
            return True
        elif cross_product(hull[0], hull[i], hull[j]) == 0:
            return True
    return True

