def solution(board_str):
    """
    Solve the hexagonal chocolate game to determine who wins.
    """
    # Parse the board into lines and cells
    lines = [line.strip() for line in board_str.strip().split('\n')]

    if not lines:
        return 'Lillebror\n'

    # Parse each line into cells
    grid = []
    for line in lines:
        if line.strip():
            grid.append(line.strip().split())

    if not grid:
        return 'Lillebror\n'

    num_rows = len(grid)

    # Define index mapping: for hexagon with 19 cells
    # We map each cell to a unique index 0-18
    # Using a simple row-major mapping with padding for consistent indexing
    def cell_idx(r, c):
        # Max columns needed for 5-row hexagon
        return r * 5 + c

    # Build state: bitmask representing which cells have chocolates
    # First, identify which positions exist in the grid
    existing_positions = set()
    for r in range(num_rows):
        for c in range(len(grid[r])):
            existing_positions.add((r, c))

    # Three directions in hexagonal grid (horizontal + diagonals)
    # Direction vectors for finding consecutive cells
    directions = [(0, 1), (1, -1), (1, 0)]

    # Use memoization to determine if current state is winning
    @lru_cache(maxsize=None)
    def can_force_win(state):
        """Returns True if current player can force a win from this state."""

        # No chocolates means player who's to move loses
        if state == 0:
            return False

        # Try all possible moves
        for r in range(num_rows):
            for c in range(len(grid[r])):
                if (r, c) not in existing_positions:
                    continue
                if not ((state >> cell_idx(r, c)) & 1):
                    continue

                # Check each direction for consecutive chocolates
                for dr, dc in directions:
                    # Find sequence starting from (r, c)
                    start_idx = cell_idx(r, c)
                    if not ((state >> start_idx) & 1):
                        continue

                    seq = []
                    for i in range(1, 5):  # Check up to 5 consecutive cells
                        nr, nc = r + dr * i, c + dc * i
                        idx = cell_idx(nr, nc)
                        if (nr, nc) in existing_positions and ((state >> idx) & 1):
                            seq.append(idx)
                        else:
                            break

                    # Need at least 2 chocolates in sequence for a valid move
                    if len(seq) < 1:
                        continue

                    # Apply move: remove all chocolates in sequence
                    removed = sum(1 << idx for idx in seq)
                    new_state = state ^ removed  # XOR removes the bits

                    # If any move leads to opponent losing, this is a winning move
                    if not can_force_win(new_state):
                        return True

        # No winning moves available
        return False

    # Build initial state
    initial_state = 0
    for r in range(num_rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 'O':
                initial_state |= (1 << cell_idx(r, c))

    return 'Karlsson\n' if can_force_win(initial_state) else 'Lillebror\n'

