        components = []

        # Get all contact points in any wire
        all_points = set()
        for x, y in wires:
            all_points.add(x)
            all_points.add(y)

        for point in all_points:
            if point not in visited:
                component = set()
                stack = [point]
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    component.add(node)
                    for neighbor in adj.get(node, []):
                        if neighbor not in visited:
                            stack.append(neighbor)
                if component:
                    components.append(component)

        k = len(components)
        if k == 1:
            # All wires connected
            results.append('0')
        else:
            # Need k-1 operations
            # Hub point we'll connect to
            hub = components[0].pop()
            components[0].add(hub)

            results.append(str(k - 1))

            for i in range(1, k):
                # Pick the first component for its hub
                comp_hubs = {}
                for j, comp in enumerate(components):
                    comp_hubs[j] = list(comp)[0]

                # Get the component index for current i
                # Actually we need to work with the components list
                # Let me use the component at index i-1 as the target to change
                # and component at index i as the source

                # Better: for each component i > 0, pick a wire from it and change one endpoint to hub
                # Find which component each wire belongs to
                wire_to_component = {}
                comp_to_wire = {}  # comp_idx -> first wire in component

                for comp_idx, comp in enumerate(components):
                    # Find a wire that has both endpoints in this component
                    for w_idx, (x, y) in enumerate(wires):
                        if x in comp or y in comp:
                            if comp_idx not in comp_to_wire:
                                comp_to_wire[comp_idx] = w_idx
                            break

                # For components 1 to k-1, connect to hub
                for comp_idx in range(1, k):
                    w_idx = comp_to_wire[comp_idx]
                    x, y = wires[w_idx]

                    # Change one endpoint to hub
                    if x == hub:
                        # Change y to hub
                        results.append(f"{w_idx + 1} {y} {hub}")
                    else:
                        # Change x to hub (or y if needed to be distinct)
                        if x == y:
                            continue  # Shouldn't happen by problem constraints
                        results.append(f"{w_idx + 1} {x} {hub}")
                        wires[w_idx] = (hub, y)

            results.append('\n'.join(results[-1]))
            del results[-1]

    return '\n'.join(results)

