def is_complete_full_binary_tree(adj, num_nodes, root):
    """
    Check if the given tree starting from 'root' is a complete full binary tree.
    A complete full binary tree has:
    - Root at depth 0 with 2 children
    - Internal nodes at depth < max_depth with exactly 2 children each
    - All leaf nodes at depth == max_depth with 0 children
    - Total nodes = 2^(max_depth+1) - 1
    """
    visited = {root}
    depth = {root: 0}
    children = {root: []}
    queue = deque([root])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                depth[v] = depth[u] + 1
                children[u].append(v)
                queue.append(v)

    if len(depth) != num_nodes:
        return False

    max_depth = max(depth.values())

    for u in children:
        d = depth.get(u, 0)
        if d < max_depth:
            # Internal node must have exactly 2 children
            if len(children[u]) != 2:
                return False
        else:
            # Leaf node must have 0 children
            if len(children[u]) != 0:
                return False

    return True

