    # Precompute smallest prime factor for Sieve of Eratosthenes
    spf = list(range(MAX_N))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N, i):
                if spf[j] == j:
                    spf[j] = i

    def get_prime_count(n):
        """Returns the number of distinct prime factors of n"""
        if n <= 1:
            return 0
        cnt = 0
        temp = n
        while temp > 1:
            p = spf[temp]
            cnt += 1
            while temp % p == 0:
                temp //= p
        return cnt

    def compute_f0(n):
        """f0(n) = 2^(number of distinct prime factors)"""
        if n == 1:
            return 1
        k = get_prime_count(n)
        return pow(2, k, MOD)

    results = []

