                # When r is small, ans grows with r

                # Final formula based on pattern matching
                base = f0_val
                mult = 1
                for i_num in range(1, r + 1):
                    mult = (mult * base) % MOD
                ans = mult % MOD

        results.append(str(ans))

    return '\n'.join(results)

