def solution(input_data: str) -> str:
    lines = input_data.strip().split('\n')
    if not lines:
        return ''

    idx = 0
    n, m = int(lines[idx]), int(lines[idx + 1])
    idx += 2

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        a, b, l = map(int, lines[idx].split())
        idx += 1
        adj[a].append((b, l))

    q_idx = idx
    while idx < len(lines) and not lines[idx].strip():
        idx += 1
    idx += 1  # Read q
    q = int(lines[q_idx]) if q_idx < len(lines) else 0
    idx = q_idx + 1

    queries = []
    for _ in range(q):
        v, s, t = map(int, lines[idx].split())
        idx += 1
        queries.append((v, s, t))

    parent = list(range(n + 1))
    cycle_gcd = [0] * (n + 1)

    def find(x):
        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        for node in path:
            parent[node] = x
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx
            cycle_gcd[rx] = math.gcd(cycle_gcd[rx], cycle_gcd[ry])

    # DFS to detect cycles
    visited = [False] * (n + 1)
    dist = [-1] * (n + 1)
    par = [-1] * (n + 1)

    def dfs(start):
        stack = [(start, 0, -1)]  # node, distance, parent
        while stack:
            node, d, p = stack.pop()
            if not visited[node]:
                visited[node] = True
                dist[node] = d
                par[node] = p

            for nxt, w in adj[node]:
                visited_in_stack = node in stack

                if not visited[nxt]:
                    union(node, nxt)
                    stack.append((nxt, d + w, node))
                elif nxt != p:
                    cycle_len = d - dist[nxt]
                    union(node, node)  # Update gcd for this component
                    root = find(node)
                    cycle_gcd[root] = math.gcd(cycle_gcd[root], cycle_len)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    results = []
    for v, s, t in queries:
        if s % t == 0:
            results.append('YES')
            continue

        root = find(v)
        g = cycle_gcd[root]

        # We can adjust total distance by multiples of g
        # Need: (s + L) % t == 0 where L = k*g
        # This means gcd(g, t) must divide s
        if g == 0:
            results.append('NO')
        else:
            if s % math.gcd(g, t) == 0:
                results.append('YES')
            else:
                results.append('NO')

    return '\n'.join(results)

