import os

def is_valid_set_score(pa, pb):
    """
    Check if a set score (pa, pb) is valid according to volleyball rules.
    """
    if pa == pb:
        return False

    if pa > pb:  # Team A won this set
        if pa < 25:
            return False
        if pb >= 24:  # Deuce situation
            return pa - pb >= 2
    else:  # pb > pa, Team B won this set
        if pb < 25:
            return False
        if pa >= 24:  # Deuce situation
            return pb - pa >= 2

    return True

