def partition_3_sets(a_total, b_total, valid_sets):
    """Try to partition 3 sets that sum to a_total and b_total"""
    import itertools

    for combo in itertools.combinations(valid_sets, 3):
        if sum(s[0] for s in combo) == a_total and sum(s[1] for s in combo) == b_total:
            return combo
    return None

def partition_sets(a_total, b_total, valid_sets, a_wins, b_wins):
    """Try to partition sets for general case"""
    import itertools

    total_sets = a_wins + b_wins

    # For simplicity, try all combinations
    for combo in itertools.combinations(valid_sets, total_sets):
        total_a = sum(s[0] for s in combo)
        total_b = sum(s[1] for s in combo)

        if total_a == a_total and total_b == b_total:
            return list(combo)

    return None

